//go:build ignore

// Standalone legacy dictionary check. No diameterkit imports or generated bytes.
package main

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/ctrlzy/go-diameter/v4/diam"
	"github.com/ctrlzy/go-diameter/v4/diam/datatype"
	"github.com/ctrlzy/go-diameter/v4/diam/dict"
)

func must(err error) {
	if err != nil {
		panic(err)
	}
}
func load(name string) []byte {
	b, e := os.ReadFile(filepath.Join(os.Args[1], name+".hex"))
	must(e)
	b, e = hex.DecodeString(strings.Join(strings.Fields(string(b)), ""))
	must(e)
	return b
}
func check(a *diam.AVP) {
	if a.VendorID == 10415 {
		switch a.Code {
		case 3102, 3316, 3320, 3324:
			g, ok := a.Data.(*diam.GroupedAVP)
			if !ok {
				panic("group type")
			}
			for _, c := range g.AVP {
				check(c)
			}
		case 701:
			if _, ok := a.Data.(datatype.OctetString); !ok {
				panic("MSISDN type")
			}
		case 3329:
			if _, ok := a.Data.(datatype.Time); !ok {
				panic("Time type")
			}
		case 3325:
			if _, ok := a.Data.(datatype.OctetString); !ok {
				panic("legacy HSS-ID type changed")
			}
		case 3326, 3327:
			if _, ok := a.Data.(datatype.UTF8String); !ok {
				panic("URI type")
			}
		}
	} else if a.VendorID == 0 && a.Code == 1 {
		if _, ok := a.Data.(datatype.UTF8String); !ok {
			panic("User-Name type")
		}
	} else if a.Code == 3327 {
		if _, ok := a.Data.(datatype.Unknown); !ok {
			panic("wrong-vendor shadow")
		}
	}
}
func main() {
	if len(os.Args) != 2 {
		panic("fixture directory required")
	}
	for _, name := range []string{"v21-ims-srr-r", "v21-ims-srr-a", "v21-ims-srr-f", "n26-srr-hssid-nested", "n26-srr-originuri", "n27-srr-uri3327", "b34-no-uri", "b34-dup-uri", "b34-dup-group", "b34-hssid5", "b34-hssid6", "b34-hssid16", "b34-both-ids", "b34-uri-params", "b34-uri-escaped", "b34-wrong-vendor", "b34-sra-noimsi", "b34-sra-samebytes", "b34-sra-5550", "b34-sra-5552", "b34-sra-5556", "b34-sra-5557"} {
		raw := load(name)
		m, e := diam.ReadMessage(bytes.NewReader(raw), dict.Default)
		must(e)
		if m.Header.ApplicationID != 16777312 || m.Header.CommandCode != 8388647 || m.Header.HopByHopID != 0x21210003 || m.Header.EndToEndID != 0x31310003 {
			panic("original routing pair header")
		}
		session := false
		for _, a := range m.AVP {
			check(a)
			if a.Code == 263 {
				session = string(a.Data.Serialize()) == "gmsc.example;21;3"
			}
		}
		if !session {
			panic("original routing pair session")
		}
		out, e := m.Serialize()
		must(e)
		if !bytes.Equal(raw, out) {
			panic("reencode")
		}
		fmt.Printf("PASS %s (%d bytes): original routing pair header/session, Grouped/UTF8 URI and top User-Name and exact reencode; legacy nested HSS-ID OctetString and semantic counterexamples are not conformance\n", name, len(raw))
	}
}
